import XCTest

final class RepostTestUITests: XCTestCase {
    func testStep() throws {
        let env = ProcessInfo.processInfo.environment
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        let step = env["STEP"] ?? "noop"
        NSLog("STEP=\(step)")
        switch step {
        case "tap":
            let px = Double(env["PX"] ?? "0")!
            let py = Double(env["PY"] ?? "0")!
            let sw = Double(env["SW"] ?? "1179")!
            let sh = Double(env["SH"] ?? "2556")!
            app.coordinate(withNormalizedOffset: CGVector(dx: px / sw, dy: py / sh)).tap()
            Thread.sleep(forTimeInterval: 2)
        case "type":
            app.typeText(env["TEXT"] ?? "")
            Thread.sleep(forTimeInterval: 1)
        case "tapLabel":
            let label = env["LABEL"] ?? ""
            let el = app.descendants(matching: .any).matching(NSPredicate(format: "label == %@", label)).firstMatch
            if el.waitForExistence(timeout: 6) {
                el.tap()
                NSLog("TAPPED \(label)")
            } else {
                NSLog("NOTFOUND \(label)")
            }
            Thread.sleep(forTimeInterval: 2)
        default:
            break
        }
    }
}

import XCTest

final class RepostTestUITests: XCTestCase {
    func testQuotePost() throws {
        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.launch()

        let feed = app.descendants(matching: .any).matching(NSPredicate(format: "label CONTAINS 'whiskers'")).firstMatch
        XCTAssertTrue(feed.waitForExistence(timeout: 45), "feed did not load")
        NSLog("FEED_READY")
        Thread.sleep(forTimeInterval: 2)

        app.coordinate(withNormalizedOffset: CGVector(dx: 458.0 / 1179.0, dy: 1772.0 / 2556.0)).tap()
        NSLog("TAPPED_REPOST")
        Thread.sleep(forTimeInterval: 2.5)

        let quote = app.descendants(matching: .any).matching(NSPredicate(format: "label == 'Quote post'")).firstMatch
        if quote.waitForExistence(timeout: 6) {
            quote.tap()
            NSLog("TAPPED_QUOTE")
        } else {
            let snap = try? app.snapshot()
            if let snap { NSLog("MENU_DUMP:\n\(dump(snap, 0))") }
            XCTFail("Quote post not found")
            return
        }
        Thread.sleep(forTimeInterval: 3)

        let field = app.textViews.firstMatch
        if field.waitForExistence(timeout: 8) {
            field.tap()
            NSLog("TAPPED_FIELD")
        }
        Thread.sleep(forTimeInterval: 1)
        app.typeText("sharing this")
        NSLog("TYPED")
        Thread.sleep(forTimeInterval: 1.5)

        let post = app.buttons.matching(NSPredicate(format: "label == 'Post'")).firstMatch
        if post.waitForExistence(timeout: 6) {
            post.tap()
            NSLog("TAPPED_POST")
        } else {
            let snap = try? app.snapshot()
            if let snap { NSLog("COMPOSER_DUMP:\n\(dump(snap, 0))") }
            XCTFail("Post button not found")
            return
        }
        Thread.sleep(forTimeInterval: 3)
        NSLog("DONE")
    }

    func dump(_ s: any XCUIElementSnapshot, _ depth: Int) -> String {
        var line = String(repeating: "  ", count: depth)
        line += "\(s.elementType) label=\(String(describing: s.label)) id=\(s.identifier) frame=\(s.frame)\n"
        if depth < 8 {
            for c in s.children { line += dump(c, depth + 1) }
        }
        return line
    }
}

